function place(el, x, y) {
  el.style.left = `${x}px`;
  el.style.top = `${y}px`;
  return el;
}

function textBox(className, text, x, y, width) {
  const el = document.createElement('div');
  el.className = className;
  el.innerHTML = text.replace(/\n/g, '<br>');
  place(el, x, y);
  if (width !== null && width !== undefined) el.style.width = `${width}px`;
  return el;
}

function makePanel(mark, title, panelClasses = '') {
  const panel = document.createElement('section');
  panel.className = `figure-panel ${panelClasses}`.trim();

  const titleEl = document.createElement('div');
  titleEl.className = 'panel-title';
  titleEl.textContent = title;

  const markEl = document.createElement('div');
  markEl.className = 'panel-mark';
  markEl.textContent = mark;

  const canvas = document.createElement('div');
  canvas.className = 'panel-canvas';

  panel.append(titleEl, canvas, markEl);
  return { panel, canvas };
}

function addCueArrow(frame, rotationDeg = 45) {
  const arrow = document.createElement('img');
  arrow.className = 'cue-arrow';
  arrow.src = ARROW_ASSET_URL;
  arrow.alt = 'rotation cue';
  arrow.style.transform = `translate(-50%, -50%) rotate(${rotationDeg}deg)`;
  frame.wrapper.appendChild(arrow);
}

function fmtNumber(value) {
  return Number(value)
    .toFixed(3)
    .replace(/\.?0+$/, '');
}

function scaleCircle(el, factor) {
  if (!el) return;
  const r = Number(el.getAttribute('r'));
  if (Number.isFinite(r)) el.setAttribute('r', fmtNumber(r * factor));
}

function scaleRect(el, factor, strokeFactor = 1.15) {
  if (!el) return;
  const x = Number(el.getAttribute('x'));
  const y = Number(el.getAttribute('y'));
  const width = Number(el.getAttribute('width'));
  const height = Number(el.getAttribute('height'));
  if (![x, y, width, height].every(Number.isFinite)) return;
  const cx = x + width / 2;
  const cy = y + height / 2;
  const newWidth = width * factor;
  const newHeight = height * factor;
  el.setAttribute('x', fmtNumber(cx - newWidth / 2));
  el.setAttribute('y', fmtNumber(cy - newHeight / 2));
  el.setAttribute('width', fmtNumber(newWidth));
  el.setAttribute('height', fmtNumber(newHeight));
  const strokeWidth = Number(el.getAttribute('stroke-width'));
  if (Number.isFinite(strokeWidth)) {
    el.setAttribute('stroke-width', fmtNumber(strokeWidth * strokeFactor));
  }
}

function scalePolygon(el, factor) {
  if (!el) return;
  const raw = el.getAttribute('points');
  if (!raw) return;
  const points = raw
    .trim()
    .split(/\s+/)
    .map((pair) => pair.split(',').map(Number))
    .filter(([x, y]) => Number.isFinite(x) && Number.isFinite(y));
  if (!points.length) return;
  const xs = points.map(([x]) => x);
  const ys = points.map(([, y]) => y);
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2;
  const cy = (Math.min(...ys) + Math.max(...ys)) / 2;
  const scaled = points
    .map(([x, y]) => `${fmtNumber(cx + (x - cx) * factor)},${fmtNumber(cy + (y - cy) * factor)}`)
    .join(' ');
  el.setAttribute('points', scaled);
}

function enhanceFigureFrame(frame) {
  const ring = frame.wrapper.querySelector('.grid-bullseye-ring');
  if (ring) {
    ring.setAttribute('stroke', FIGURE_RING_COLOUR);
    ring.setAttribute('stroke-width', '0.78');
  }

  if (frame.centerDot) {
    frame.centerDot.setAttribute('fill', FIGURE_CENTER_DOT_COLOUR);
    scaleCircle(frame.centerDot, 1.35);
  }

  if (frame.fixationEl) {
    frame.fixationEl.setAttribute('fill', FIGURE_FIXATION_COLOUR);
    frame.fixationEl.setAttribute('font-size', '10.4');
  }

  frame.wrapper.querySelectorAll('.dot').forEach((el) => scaleCircle(el, DEMO_DOT_SCALE));
  frame.wrapper.querySelectorAll('.dummy-open-square').forEach((el) => {
    scaleRect(el, DEMO_SQUARE_SCALE, 1.35);
    el.setAttribute('stroke', FIGURE_SQUARE_COLOUR);
  });
  frame.wrapper.querySelectorAll('.star').forEach((el) => scalePolygon(el, DEMO_STAR_SCALE));
}

function frameScene({
  rotation_deg = 0,
  fixation = '',
  show_pattern = false,
  dot_cell = null,
  dot_color = '#fff',
  square_cell = null,
  star_cell = null,
  star_color = '#fff',
  arrow_deg = null,
} = {}) {
  return (mount) => {
    const frame = createGridFrame({ rotation_deg, fixation });
    mount.appendChild(frame.wrapper);

    if (show_pattern) {
      buildPatternOverlay(frame);
      showPattern(frame);
    }
    if (typeof dot_cell === 'number') addDot(frame, dot_cell, { color: dot_color });
    if (typeof square_cell === 'number') addOpenSquare(frame, square_cell);
    if (typeof star_cell === 'number') addStar(frame, star_cell, { color: star_color });
    if (typeof arrow_deg === 'number') addCueArrow(frame, arrow_deg);
    enhanceFigureFrame(frame);

    return frame;
  };
}

function makeCard(scene, { badge = '' } = {}) {
  const card = document.createElement('div');
  card.className = 'screen-card';

  const mount = document.createElement('div');
  mount.className = 'screen-mount';
  card.appendChild(mount);
  scene(mount);

  if (badge) {
    const badgeEl = document.createElement('div');
    badgeEl.className = 'tone-badge';
    badgeEl.textContent = badge;
    card.appendChild(badgeEl);
  }

  return card;
}

function discreteCard(canvas, scene, x, y, opts = {}) {
  const card = makeCard(scene, opts);
  place(card, x, y);
  canvas.append(card);
  return card;
}

function makeQueue(sceneSpecs) {
  const stack = document.createElement('div');
  stack.className = 'card-stack';

  let cursorX = 0;
  let cursorY = 0;
  let maxX = CARD_W;
  let maxY = CARD_H;

  sceneSpecs.forEach((spec, index) => {
    const kind = spec.kind ?? 'stim';
    const lift = kind === 'frame' ? FRAME_LIFT : 0;
    const x = cursorX + (spec.offsetX ?? 0);
    const y = cursorY + (spec.offsetY ?? lift);
    const card = makeCard(spec.scene, { badge: spec.badge ?? '' });
    place(card, x, y);
    stack.appendChild(card);
    maxX = Math.max(maxX, x + CARD_W);
    maxY = Math.max(maxY, y + CARD_H);

    if (index < sceneSpecs.length - 1) {
      const nextKind = sceneSpecs[index + 1].kind ?? 'stim';
      const useFrame = kind === 'frame' || nextKind === 'frame';
      cursorX += useFrame ? FRAME_DX : STIM_DX;
      cursorY += useFrame ? FRAME_DY : STIM_DY;
    }
  });

  stack.style.width = `${maxX}px`;
  stack.style.height = `${maxY}px`;
  return stack;
}

