  const visualFeedback = makeCard(
    frameScene({ fixation: '?', dot_cell: offCells[4], dot_color: FEEDBACK_GREEN })
  );
  const auditoryFeedback = makeCard((mount) => {
    const frame = createGridFrame({ rotation_deg: 0, fixation: '?' });
    mount.appendChild(frame.wrapper);
    setFixation(frame, '?', { color: FEEDBACK_GREEN });
  });

  place(placeholder, 40, 72);
  place(star, 296, 72);
  place(visualFeedback, 40, 368);
  place(auditoryFeedback, 296, 368);
